function uploadProfileImage(file,kind){return new Promise(async(resolve,reject)=>{if(!file)return resolve(null);const max=kind==='banner'?8*1024*1024:5*1024*1024;if(!/^image\/(png|jpeg|webp)$/.test(file.type))return reject(new Error('Choose a JPG, PNG or WebP image.'));if(file.size>max)return reject(new Error(`Image must be under ${kind==='banner'?8:5} MB.`));const ext=file.type==='image/jpeg'?'jpg':file.type.split('/')[1];const path=`${user.id}/${kind}-${crypto.randomUUID()}.${ext}`;const up=await db.storage.from('profile-media').upload(path,file,{upsert:true,contentType:file.type});if(up.error)return reject(up.error);resolve(db.storage.from('profile-media').getPublicUrl(path).data.publicUrl)})}
