async function loadData(){if(!db){empty('Could not connect to Supabase. Check the project URL and publishable key.');return}$('content').innerHTML='<div class="empty">Loading Loobee…</div>';msg('status','');let q=db.from('videos').select('id,title,description,category,video_url,thumbnail_url,created_at,user_id,is_private,comments_enabled,is_short,view_count,hype_count,quality_urls,profiles(username,display_name,is_verified)').order('created_at',{ascending:false}).limit(100);if(category!=='All')q=q.eq('category',category);if(searchTerm)q=q.ilike('title',`%${searchTerm.replace(/[%_,]/g,' ')}%`);if(page==='myvideos'){if(!user){empty('Sign in to see your videos.');return}q=q.eq('user_id',user.id)}if(page==='subscriptions'){if(!user){empty('Sign in to see your subscriptions.');return}const{sdata,serror}=await Promise.resolve({sdata:null,serror:null});const{data:subs,error:subError}=await db.from('subscriptions').select('channel_id').eq('subscriber_id',user.id);if(subError){msg('status',subError.message,true);return}const ids=(subs||[]).map(x=>x.channel_id);if(!ids.length){empty('You have not subscribed to any channels yet.');return}q=q.in('user_id',ids)}if(page==='channels'){await loadChannels();return}if(page==='warnings'){await renderWarningsPage();return}if(page==='shorts'){q=q.eq('is_short',true)}const{data,error}=await q;if(error){msg('status','Could not load videos: '+error.message,true);$('content').innerHTML='';return}videos=shuffleVideos((data||[]).filter(v=>(!v.is_private||v.user_id===user?.id)&&(page==='shorts'?v.is_short===true:v.is_short!==true)));renderVideos(videos)}
