function configureVideoQuality(v){const sel=$('qualitySelect');if(!sel)return;sel.replaceChildren();const variants=v.quality_urls&&typeof v.quality_urls==='object'?v.quality_urls:{};const options=[['auto','Auto / Original',true]];for(const [key,label] of [['144p','144p'],['240p','240p'],['360p','360p'],['480p','480p'],['720p','720p HD'],['1080p','1080p Full HD'],['1440p','1440p QHD / 2K'],['2160p','2160p 4K']])options.push([key,label,typeof variants[key]==='string'&&!!variants[key]]);for(const [value,label,available] of options){const o=document.createElement('option');o.value=value;o.textContent=available?label:label+' · not uploaded';o.disabled=!available;o.title=available?'Switch to this uploaded video version':'This video does not have this quality version uploaded';sel.append(o)}sel.value='auto';sel.disabled=false;sel.onchange=()=>{const target=sel.value==='auto'?v.video_url:variants[sel.value];if(!target)return;const player=$('watchPlayer'),wasPlaying=!player.paused,oldTime=player.currentTime;player.src=target;player.load();player.addEventListener('loadedmetadata',function restore(){player.removeEventListener('loadedmetadata',restore);try{player.currentTime=oldTime}catch{}if(wasPlaying)player.play().catch(()=>{})});$('qualityInfo').textContent='Quality: '+(sel.value==='auto'?'Auto / original upload':sel.options[sel.selectedIndex].text)+' · quality changes only when that version exists.'};$('qualityInfo').textContent='Choose Auto or an uploaded version. Greyed-out qualities need to be uploaded first.'}
