async function loadRecommendations(){const{data,error}=await db.from('videos').select('id,title,thumbnail_url,created_at,user_id,profiles(username,display_name,is_verified)').eq('is_private',false).neq('is_short',true).limit(100);const box=$('recommendations');box.replaceChildren();if(error||!data?.length){box.textContent='No other videos found.';return}for(const v of shuffleVideos(data.filter(x=>x.id!==currentVideo.id)).slice(0,20)){const row=document.createElement('div');row.className='recommendation';row.onclick=()=>openVideo(v.id,true);const thumb=document.createElement('div');thumb.className='thumb';if(v.thumbnail_url){const img=document.createElement('img');img.src=v.thumbnail_url;img.alt='';thumb.append(img)}else thumb.textContent='▶';const info=document.createElement('div');const title=document.createElement('h3');title.textContent=v.title||'Untitled video';const channel=document.createElement('div');channel.className='meta';channel.textContent=v.profiles?.display_name||v.profiles?.username||'Loobee creator';const date=document.createElement('div');date.className='meta';date.textContent=v.created_at?new Date(v.created_at).toLocaleDateString():'';info.append(title,channel,date);row.append(thumb,info);box.append(row)}}
function renderAbout(text){const box=$('profileAbout');box.replaceChildren();const raw=String(text||'');if(!raw){box.textContent='No about information yet.';return}const urlPattern=/(https?:\/\/[^\s]+|www\.[^\s]+)/gi;let last=0;for(const match of raw.matchAll(urlPattern)){const index=match.index;if(index>last)box.append(document.createTextNode(raw.slice(last,index)));let value=match[0];let clean=value.replace(/[.,!?;:)]+$/,'');let trailing=value.slice(clean.length);const a=document.createElement('a');a.href=clean.startsWith('www.')?'https://'+clean:clean;a.textContent=clean;a.target='_blank';a.rel='noopener noreferrer';box.append(a,document.createTextNode(trailing));last=index+value.length}if(last<raw.length)box.append(document.createTextNode(raw.slice(last)))}
async function openProfile(id,from='browse'){if(!db||!id)return;if(!user){showModal('authModal');msg('authMessage','You need to sign in to view profiles.');return}profileReturnView=from;viewedProfileId=id;$('profileNotice').textContent='Loading profile…';$('profileEditPanel').classList.add('hidden');$('profileVideos').innerHTML='<div class="empty">Loading videos…</div>';showProfileView(true);$('browseView').classList.add('hidden');$('watchView').classList.add('hidden');const{data:profile,error}=await db.from('profiles').select('id,username,display_name,about,avatar_url,banner_url,created_at,is_verified').eq('id',id).maybeSingle();if(error){$('profileNotice').textContent='Could not load profile: '+error.message;return}if(!profile){$('profileName').textContent='Profile not found';$('profileNotice').textContent='This user profile does not exist yet.';return}const username=profile.username||'Creator';const displayName=profile.display_name||username;profileUsernameRaw=username;profileDisplayNameRaw=displayName;profileAboutRaw=profile.about||'';$('profileName').innerHTML=esc(displayName)+verifiedBadge(profile.is_verified);$('profileEmail').textContent='@'+username;setImageOrInitial($('profileAvatar'),profile.avatar_url,(displayName[0]||'?').toUpperCase());$('profileHero').style.setProperty('--profile-banner',profile.banner_url?`url(\"${profile.banner_url.replace(/\"/g,'')}\")`:'linear-gradient(120deg,#8b5cf633,#ff31551a)');renderAbout(profileAboutRaw);const own=!!user&&user.id===id;$('editProfileBtn').classList.toggle('hidden',!own);$('securityOpenBtn').classList.toggle('hidden',!own);$('profileSubscribeBtn').classList.toggle('hidden',own);if(!own){const{data:sub}=await db.from('subscriptions').select('subscriber_id').eq('subscriber_id',user.id).eq('channel_id',id).maybeSingle();$('profileSubscribeBtn').textContent=sub?'Subscribed':'Subscribe'}const{data:items,error:videoError}=await db.from('videos').select('id,title,description,category,video_url,thumbnail_url,created_at,user_id,is_private,comments_enabled,is_short,view_count,hype_count,quality_urls,profiles(username,display_name,is_verified)').eq('user_id',id).order('created_at',{ascending:false});if(videoError){$('profileVideos').textContent='Could not load videos: '+videoError.message;return}const visible=shuffleVideos((items||[]).filter(v=>(!v.is_private||v.user_id===user.id)&&v.is_short!==true));if(!visible.length){$('profileVideos').innerHTML='<div class="empty">No public videos yet.</div>';return}$('profileVideos').innerHTML=visible.map(v=>`<article class="video" data-profile-video="${esc(v.id)}"><div class="thumb">${v.thumbnail_url?`<img loading="lazy" src="${esc(v.thumbnail_url)}" alt="">`:'<span>No thumbnail</span>'}<span class="play">▶</span></div><h3>${esc(v.title||'Untitled video')}${v.is_private?' 🔒':''}</h3><div class="meta">${esc(username)}${verifiedBadge(profile.is_verified)}<br>${v.created_at?new Date(v.created_at).toLocaleDateString():''} · ${Number(v.view_count||0).toLocaleString()} views · 🔥 ${Number(v.hype_count||0).toLocaleString()}</div></article>`).join('');document.querySelectorAll('[data-profile-video]').forEach(el=>el.onclick=()=>openVideo(el.dataset.profileVideo,true))}
