async function makeVideoThumbnail(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),video=document.createElement('video');video.preload='metadata';video.muted=true;video.playsInline=true;let finished=false;const cleanup=()=>{URL.revokeObjectURL(url);video.removeAttribute('src');video.load()};const fail=()=>{if(finished)return;finished=true;cleanup();reject(new Error('Could not create a thumbnail from this video. Try uploading a JPG/PNG thumbnail instead.'))};video.onerror=fail;video.onloadedmetadata=()=>{try{const target=Number.isFinite(video.duration)&&video.duration>0?Math.min(1,video.duration/2):0;video.currentTime=target}catch{fail()}};video.onseeked=()=>{if(finished)return;try{const width=video.videoWidth,height=video.videoHeight;if(!width||!height)throw new Error('Video has no readable frame.');const max=640,scale=Math.min(1,max/Math.max(width,height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(width*scale));canvas.height=Math.max(1,Math.round(height*scale));const ctx=canvas.getContext('2d');if(!ctx)throw new Error('Canvas is unavailable.');ctx.drawImage(video,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>{if(finished)return;finished=true;cleanup();if(blob)resolve(new File([blob],'video-thumbnail.jpg',{type:'image/jpeg'}));else reject(new Error('Could not encode the video thumbnail.'))},'image/jpeg',0.82)}catch{fail()}};video.src=url;video.load()})}
$('uploadForm').onsubmit=async e=>{e.preventDefault();if(!db||!user){msg('uploadMessage','Sign in before uploading.',true);return}const file=$('videoFile').files[0],thumb=$('thumbnailFile').files[0];if(!file||!file.type.startsWith('video/'))return msg('uploadMessage','Choose a valid video file.',true);if(file.size>500*1024*1024)return msg('uploadMessage','Video must be under 500 MB.',true);if($('uploadPrivate').checked)return msg('uploadMessage','Private upload is disabled here until the Storage bucket is made private and signed URLs are implemented. Upload publicly for now, or configure secure private Storage first.',true);msg('uploadMessage','Uploading video…');try{const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'_'),path=`${user.id}/${crypto.randomUUID()}-${safe}`;const up=await db.storage.from('videos').upload(path,file,{upsert:false,contentType:file.type});if(up.error)throw up.error;const videoUrl=db.storage.from('videos').getPublicUrl(path).data.publicUrl;let thumbnailUrl=null;let thumbnailToUpload=thumb||null;if(!thumbnailToUpload){msg('uploadMessage','No thumbnail selected — creating one from your video…');thumbnailToUpload=await makeVideoThumbnail(file)}if(thumbnailToUpload){if(thumbnailToUpload.size>5*1024*1024)throw new Error('Thumbnail must be under 5 MB.');const thumbName=thumb?thumb.name:'video-thumbnail.jpg';const tp=`${user.id}/${crypto.randomUUID()}-${thumbName.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const tu=await db.storage.from('thumbnails').upload(tp,thumbnailToUpload,{upsert:false,contentType:thumbnailToUpload.type||'image/jpeg'});if(tu.error)throw tu.error;thumbnailUrl=db.storage.from('thumbnails').getPublicUrl(tp).data.publicUrl}const{error}=await db.from('videos').insert({user_id:user.id,title:$('videoTitle').value.trim(),description:$('videoDescription').value.trim(),category:$('videoCategory').value,video_url:videoUrl,thumbnail_url:thumbnailUrl,is_private:false,comments_enabled:true,is_short:$('uploadShort').checked});if(error)throw error;msg('uploadMessage','Video uploaded successfully!');$('uploadForm').reset();showModal('uploadModal',false);page='home';showBrowse();await loadData()}catch(err){msg('uploadMessage','Upload failed: '+(err.message||'Unknown error'),true)}};
