const OWNER_EMAIL='lowvr81@gmail.com';
$('adminOpen').onclick=()=>{if(user?.email?.toLowerCase()!==OWNER_EMAIL)return;showModal('ownerAdminModal');$('adminSearch').value='';$('adminMessage').textContent='';searchAdminUsers()};
