async function ownerAdminRequest(action,extra={}){if(!user||user.email?.toLowerCase()!==OWNER_EMAIL)throw new Error('Only the owner account can use this action.');const{data:{session}}=await db.auth.getSession();if(!session?.access_token)throw new Error('Your session expired. Please sign in again.');const res=await fetch(SUPABASE_URL+'/functions/v1/loobee-admin',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+session.access_token,'apikey':SUPABASE_KEY},body:JSON.stringify({action,...extra})});let body={};try{body=await res.json()}catch{}if(!res.ok)throw new Error(body.error||'Admin request failed ('+res.status+').');return body}
async function searchAdminUsers(){const box=$('adminResults'),status=$('adminMessage');if(user?.email?.toLowerCase()!==OWNER_EMAIL){status.textContent='Owner access required.';return}box.replaceChildren();status.textContent='Searching accounts…';try{const result=await ownerAdminRequest('search-users',{query:$('adminSearch').value.trim()});const users=result.users||[];if(!users.length){status.textContent='No matching accounts found.';return}status.textContent=users.length+' account(s) found.';for(const account of users){const card=document.createElement('section');card.className='profile-panel';const heading=document.createElement('h3');heading.textContent=(account.display_name||account.username||'Loobee user')+(account.is_verified?' ✓':'');const details=document.createElement('p');details.className='meta';details.textContent='@'+(account.username||'unknown')+' · '+(account.email||'No email available');const actions=document.createElement('div');actions.className='feature-row';const verify=document.createElement('button');verify.className='primary';verify.textContent=account.is_verified?'Remove verified badge':'Verify creator';verify.onclick=async()=>{verify.disabled=true;try{await ownerAdminRequest('set-verified',{userId:account.id,isVerified:!account.is_verified});status.textContent='Verification updated.';await searchAdminUsers()}catch(e){status.textContent='Could not update verification: '+e.message;verify.disabled=false}};actions.append(verify);if(account.email?.toLowerCase()!==OWNER_EMAIL){const del=document.createElement('button');del.className='danger';del.textContent='Delete account';del.onclick=async()=>{const reason=prompt('Reason for deleting '+(account.email||account.username)+':','Violation of Loobee community rules');if(reason===null)return;if(!reason.trim()){alert('Please enter a reason so it can be included in the email.');return}if(!confirm('Permanently delete this account, all its videos, and related data? This cannot be undone.'))return;del.disabled=true;status.textContent='Deleting account and associated videos…';try{const out=await ownerAdminRequest('delete-user',{userId:account.id,reason:reason.trim()});status.textContent='Account deleted. '+(out.emailSent?'Deletion email sent.':'Account deleted, but email could not be confirmed: '+(out.emailError||'configure email delivery secrets.'));await searchAdminUsers()}catch(e){status.textContent='Account deletion failed: '+e.message;del.disabled=false}};actions.append(del)}card.append(heading,details,actions);box.append(card)}}catch(e){status.textContent='Admin request failed: '+e.message}}
// If an account is removed by an administrator, react to the profile deletion and sign the user out.
let accountRemovalChannel=null;function watchForAccountRemoval(){if(!db)return;if(accountRemovalChannel){db.removeChannel(accountRemovalChannel);accountRemovalChannel=null}if(!user)return;const targetId=user.id;accountRemovalChannel=db.channel('loobee-account-removal-'+targetId).on('postgres_changes',{event:'DELETE',schema:'public',table:'profiles'},async payload=>{if(payload.old?.id!==targetId)return;await db.auth.signOut();setUser(null);alert('Your Loobee account has been deleted. You have been signed out.');showBrowse();await loadData()}).subscribe()}

async function init(){if(!db){empty('Supabase could not initialize. Check the project URL and publishable key.');return}const{data}=await db.auth.getSession();setUser(data.session?.user);if(user){await ensureProfile();await ensureLowVRSubscription();await enforceMfaIfEnrolled(user);watchForAccountRemoval()}db.auth.onAuthStateChange(async(_event,session)=>{setUser(session?.user);if(user){await ensureProfile();await ensureLowVRSubscription();showModal('authModal',false);await enforceMfaIfEnrolled(user);watchForAccountRemoval()}loadData()});const params=new URLSearchParams(location.search);if(params.has('v'))await openVideo(params.get('v'),false);else await loadData()}
