// Silent live refresh: keep Loobee content current without a visible refresh button or page reload.
let loobeeLiveChannel=null, liveRefreshTimer=null, livePollTimer=null, lastLiveRefresh=0, liveRefreshBusy=false;
async function refreshVisibleLoobeeView(kind='poll', payload=null){
  if(!db || document.visibilityState!=='visible' || liveRefreshBusy)return;
  liveRefreshBusy=true;
  try{
    const browseVisible=!$('browseView').classList.contains('hidden');
    const profileVisible=!$('profileView').classList.contains('hidden');
    const watchVisible=!$('watchView').classList.contains('hidden');
    if(browseVisible){ await loadData(); }
    else if(profileVisible && viewedProfileId && $('profileEditPanel').classList.contains('hidden')){
      await openProfile(viewedProfileId, profileReturnView);
    } else if(watchVisible && currentVideo){
      const id=currentVideo.id;
      const {data:v,error}=await db.from('videos').select('id,title,description,category,video_url,thumbnail_url,created_at,user_id,is_private,comments_enabled,is_short,view_count,hype_count,quality_urls,profiles(username,display_name,is_verified)').eq('id',id).maybeSingle();
      if(error || !v){redirectVideoNotFound();return;}
      if(v.is_private && v.user_id!==user?.id){history.pushState({},'',location.pathname);showBrowse();await loadData();msg('status','This video is now private.');return;}
      const sourceChanged=v.video_url!==currentVideo.video_url;
      currentVideo=v;
      $('watchTitle').textContent=v.title||'Untitled video';
      $('watchDescription').textContent=v.description||'No description provided.';
      $('watchChannel').textContent=v.profiles?.display_name||v.profiles?.username||'Loobee creator';
      $('watchStats').textContent=(v.created_at?new Date(v.created_at).toLocaleDateString():'Loobee video')+' · '+Number(v.view_count||0).toLocaleString()+' views'+(v.is_short?' · SHORT':'');
      $('watchPlayer').poster=v.thumbnail_url||'';
      $('hypeCount').textContent=Number(v.hype_count||0).toLocaleString();
      $('toggleCommentsBtn').textContent=v.comments_enabled===false?'Enable comments':'Disable comments';
      $('togglePrivateBtn').textContent=v.is_private?'Make public':'Make private';
      if(sourceChanged){$('watchPlayer').src=v.video_url||'';$('watchPlayer').load();}
      await Promise.all([loadReactions(),loadComments(),loadSubscription(),loadRecommendations()]);
    }
    lastLiveRefresh=Date.now();
  }catch(e){console.warn('Loobee background refresh failed:',e)}
  finally{liveRefreshBusy=false;}
}
function scheduleLiveRefresh(kind, payload){
  if(liveRefreshTimer)clearTimeout(liveRefreshTimer);
  liveRefreshTimer=setTimeout(()=>{liveRefreshTimer=null;refreshVisibleLoobeeView(kind,payload)},400);
}
function setupLoobeeRealtime(){
  if(!db || loobeeLiveChannel)return;
  loobeeLiveChannel=db.channel('loobee-live-updates')
    .on('postgres_changes',{event:'*',schema:'public',table:'videos'},payload=>scheduleLiveRefresh('videos',payload))
    .on('postgres_changes',{event:'*',schema:'public',table:'profiles'},payload=>scheduleLiveRefresh('profiles',payload))
    .on('postgres_changes',{event:'*',schema:'public',table:'comments'},payload=>scheduleLiveRefresh('comments',payload))
    .on('postgres_changes',{event:'*',schema:'public',table:'video_reactions'},payload=>scheduleLiveRefresh('video_reactions',payload))
    .on('postgres_changes',{event:'*',schema:'public',table:'subscriptions'},payload=>scheduleLiveRefresh('subscriptions',payload))
    .on('postgres_changes',{event:'*',schema:'public',table:'account_warnings'},payload=>scheduleLiveRefresh('account_warnings',payload))
    .on('postgres_changes',{event:'*',schema:'public',table:'video_reports'},payload=>scheduleLiveRefresh('video_reports',payload))
    .subscribe(status=>{if(status==='CHANNEL_ERROR'||status==='TIMED_OUT')console.warn('Loobee Realtime unavailable; silent polling will continue.',status);});
  // Fallback: refresh the currently visible section every 20 seconds. No reload, no refresh icon, no page flash.
  if(livePollTimer)clearInterval(livePollTimer);
  livePollTimer=setInterval(()=>{
    if(document.visibilityState!=='visible')return;
    if(Date.now()-lastLiveRefresh<15000)return;
    refreshVisibleLoobeeView('poll');
  },20000);
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible' && Date.now()-lastLiveRefresh>15000)refreshVisibleLoobeeView('visible')});
}
setupLoobeeRealtime();

// Loobee feature pack: moderation, Shorts, Hype, fullscreen, views and account tools.
async function countViewOnce(videoId){if(!db||!videoId)return;const key='loobee_viewed_'+videoId;if(sessionStorage.getItem(key))return;sessionStorage.setItem(key,'1');const{data,error}=await db.rpc('loobee_count_view',{p_video_id:videoId});if(!error&&typeof data==='number'&&currentVideo?.id===videoId){currentVideo.view_count=data;$('watchStats').textContent=(currentVideo.created_at?new Date(currentVideo.created_at).toLocaleDateString():'Loobee video')+' · '+Number(data).toLocaleString()+' views'+(currentVideo.is_short?' · SHORT':'')}}
$('fullscreenBtn').onclick=async()=>{const box=$('watchPlayer');try{if(document.fullscreenElement)await document.exitFullscreen();else if(box.requestFullscreen)await box.requestFullscreen();else if(box.webkitEnterFullscreen)box.webkitEnterFullscreen();}catch(e){$('watchNotice').textContent='Fullscreen is not available in this browser.'}};
$('hypeBtn').onclick=async()=>{if(!user){showModal('authModal');msg('authMessage','Sign in to Hype a video.');return}if(!currentVideo)return;const{data,error}=await db.rpc('loobee_hype_video',{p_video_id:currentVideo.id});if(error){$('watchNotice').textContent='Hype could not be saved. Run the Loobee feature SQL migration first. '+error.message;return}const count=Number(data??0);currentVideo.hype_count=count;$('hypeCount').textContent=count.toLocaleString();$('watchNotice').textContent='🔥 Hype added! Each account can Hype a video once.'};
$('reportBtn').onclick=()=>{if(!user){showModal('authModal');msg('authMessage','Sign in to report a video.');return}if(!currentVideo)return;showModal('reportModal');$('reportMessage').textContent=''};
$('submitReportBtn').onclick=async()=>{if(!user||!currentVideo)return;const reason=$('reportReason').value,details=$('reportDetails').value.trim();const{error}=await db.from('video_reports').insert({video_id:currentVideo.id,reporter_id:user.id,reason,details});if(error){$('reportMessage').textContent='Could not submit report. Run the Loobee feature SQL migration first. '+error.message;return}$('reportMessage').textContent='Report submitted. Thank you for helping keep Loobee safe.';$('reportDetails').value='';setTimeout(()=>showModal('reportModal',false),1200)};
$('deleteVideoBtn').onclick=async()=>{if(!user||!currentVideo||user.id!==currentVideo.user_id)return;if(!confirm('Permanently delete this video from Loobee? This cannot be undone.'))return;const video=currentVideo;try{const{error}=await db.from('videos').delete().eq('id',video.id).eq('user_id',user.id);if(error)throw error;for(const [bucket,url] of [['videos',video.video_url],['thumbnails',video.thumbnail_url]]){if(!url)continue;const marker='/object/public/'+bucket+'/';const i=url.indexOf(marker);if(i>=0){const path=decodeURIComponent(url.slice(i+marker.length).split('?')[0]);await db.storage.from(bucket).remove([path])}}$('watchNotice').textContent='Video deleted.';currentVideo=null;history.pushState({},'',location.pathname);showBrowse();await loadData()}catch(e){$('watchNotice').textContent='Could not delete video: '+e.message}};
$('accountToolsBtn').onclick=()=>{showModal('accountToolsModal');$('accountToolsMessage').textContent='';loadAccountWarnings();const admin=user?.email?.toLowerCase()==='lowvr81@gmail.com';$('adminModerationPanel').classList.toggle('hidden',!admin);if(admin)loadAdminReports()};
$('loadWarningsBtn').onclick=loadAccountWarnings;
$('refreshReportsBtn').onclick=loadAdminReports;
async function loadAdminReports(){const box=$('adminReports');if(!user||user.email?.toLowerCase()!=='lowvr81@gmail.com'){box.textContent='Admin access required.';return}box.textContent='Loading reports…';const{data,error}=await db.from('video_reports').select('id,video_id,reporter_id,reason,details,status,created_at').order('created_at',{ascending:false}).limit(100);if(error){box.textContent='Could not load reports: '+error.message;return}if(!data?.length){box.textContent='No reports to review.';return}box.replaceChildren();for(const r of data){const card=document.createElement('div');card.className='warning-card';const title=document.createElement('strong');title.textContent=`${r.reason} · ${r.status}`;const details=document.createElement('p');details.textContent=r.details||'No details provided.';const meta=document.createElement('small');meta.textContent=new Date(r.created_at).toLocaleString()+' · Video ID '+r.video_id;const row=document.createElement('div');row.className='feature-row';const reviewed=document.createElement('button');reviewed.textContent='Mark reviewed';reviewed.onclick=async()=>{const{error}=await db.from('video_reports').update({status:'reviewing'}).eq('id',r.id);if(error)alert('Could not update report: '+error.message);else loadAdminReports()};const dismiss=document.createElement('button');dismiss.textContent='Dismiss report';dismiss.onclick=async()=>{const{error}=await db.from('video_reports').update({status:'dismissed'}).eq('id',r.id);if(error)alert('Could not dismiss report: '+error.message);else loadAdminReports()};const warn=document.createElement('button');warn.textContent='Warn video creator';warn.onclick=async()=>{const{data:v,error:ve}=await db.from('videos').select('user_id,title').eq('id',r.video_id).maybeSingle();if(ve||!v){alert('Video or creator not found.');return}const reason='Reported video: '+r.reason;const detailsText=`A video you uploaded was reported. Video: ${v.title||r.video_id}. Please review Loobee community rules. Report details: ${r.details||'None supplied.'}`;const{error}=await db.from('account_warnings').insert({user_id:v.user_id,admin_email:'lowvr81@gmail.com',reason,details:detailsText});if(error)alert('Could not issue warning: '+error.message);else alert('Warning issued to the video creator.')};row.append(reviewed,dismiss,warn);card.append(title,details,meta,row);box.append(card)}}

async function loadAccountWarnings(){const box=$('accountWarnings');if(!user){box.textContent='Sign in to view warnings.';return}box.textContent='Loading warnings…';const{data,error}=await db.from('account_warnings').select('id,reason,details,created_at').eq('user_id',user.id).order('created_at',{ascending:false});if(error){box.textContent='Warnings are unavailable until the SQL migration is run: '+error.message;return}if(!data?.length){box.textContent='No account warnings.';return}box.replaceChildren();for(const w of data){const el=document.createElement('div');el.className='warning-card';const title=document.createElement('strong');title.textContent=w.reason||'Account warning';const body=document.createElement('p');body.textContent=w.details||'No extra details provided.';const date=document.createElement('small');date.textContent=new Date(w.created_at).toLocaleString();el.append(title,body,date);box.append(el)}}
async function renderWarningsPage(){if(!user){empty('Sign in to view your account warnings.');return}$('content').className='';$('content').innerHTML='<div class="profile-panel"><h2>Your account warnings</h2><div id="warningPageList">Loading…</div></div>';const{data,error}=await db.from('account_warnings').select('id,reason,details,created_at').eq('user_id',user.id).order('created_at',{ascending:false});const box=$('warningPageList');if(error){box.textContent='Could not load warnings. Run the feature SQL migration first: '+error.message;return}if(!data?.length){box.textContent='No account warnings. Keep following Loobee community rules.';return}box.replaceChildren();for(const w of data){const el=document.createElement('div');el.className='warning-card';const h=document.createElement('strong');h.textContent=w.reason||'Account warning';const p=document.createElement('p');p.textContent=w.details||'';const d=document.createElement('small');d.textContent=new Date(w.created_at).toLocaleString();el.append(h,p,d);box.append(el)}}
$('deleteAccountBtn').onclick=async()=>{if(!user)return;const box=$('accountToolsMessage');if($('deleteAccountConfirm').value!=='DELETE'){box.textContent='Type DELETE exactly to confirm.';return}if(!confirm('This permanently deletes your Loobee account. Continue?'))return;box.textContent='Requesting secure account deletion…';const{data:{session}}=await db.auth.getSession();const{data,error}=await db.functions.invoke('delete-account',{headers:{Authorization:'Bearer '+session.access_token},body:{confirmation:'DELETE'}});if(error||data?.error){box.textContent='Account deletion did not complete. Deploy the included Supabase Edge Function and try again. '+(error?.message||data?.error||'');return}await db.auth.signOut();showModal('accountToolsModal',false);showBrowse();await loadData();alert('Your Loobee account deletion request completed.')};
// Show account tools only on the owner's profile, without exposing email addresses publicly.
const originalOpenProfile=openProfile;openProfile=async function(id,from='browse'){await originalOpenProfile(id,from);if(user&&id===user.id)$('accountToolsBtn').classList.remove('hidden');else $('accountToolsBtn').classList.add('hidden')};


// Loobee HUD controller: custom playback controls, keyboard shortcuts and theater mode.
(()=>{const box=document.getElementById('loobeePlayerBox'),v=document.getElementById('watchPlayer');if(!box||!v)return;const $id=id=>document.getElementById(id);const playBtn=$id('lbPlay'),center=$id('lbCenterPlay'),seek=$id('lbSeek'),current=$id('lbCurrent'),duration=$id('lbDuration'),volume=$id('lbVolume'),mute=$id('lbMute'),speed=$id('lbSpeed'),toast=$id('lbToast');let wasSeeking=false;const fmt=n=>{if(!Number.isFinite(n)||n<0)return'0:00';const s=Math.floor(n),h=Math.floor(s/3600),m=Math.floor(s%3600/60),ss=String(s%60).padStart(2,'0');return h?`${h}:${String(m).padStart(2,'0')}:${ss}`:`${m}:${ss}`};function update(){const d=v.duration||0,t=v.currentTime||0;current.textContent=fmt(t);duration.textContent=fmt(d);if(!wasSeeking)seek.value=d?Math.round(t/d*1000):0;seek.style.setProperty('--lb-progress',`${seek.value/10}%`);const ranges=v.buffered;if(ranges.length&&d){const end=ranges.end(ranges.length-1)/d*100;$id('lbBuffer').style.width=end+'%'}playBtn.textContent=v.paused?'▶':'Ⅱ';playBtn.setAttribute('aria-label',v.paused?'Play':'Pause');box.classList.toggle('lb-playing',!v.paused);box.classList.toggle('lb-paused',v.paused)}function toggle(){if(v.paused)v.play().catch(()=>{toast.textContent='Press play again to start this video.';flashToast()});else v.pause()}function flashToast(msg){if(msg)toast.textContent=msg;toast.classList.add('show');clearTimeout(flashToast.timer);flashToast.timer=setTimeout(()=>toast.classList.remove('show'),1100)}playBtn.addEventListener('click',e=>{e.stopPropagation();toggle()});center.addEventListener('click',e=>{e.stopPropagation();toggle()});v.addEventListener('click',toggle);v.addEventListener('play',update);v.addEventListener('pause',update);v.addEventListener('timeupdate',update);v.addEventListener('durationchange',update);v.addEventListener('progress',update);v.addEventListener('loadedmetadata',update);v.addEventListener('volumechange',()=>{mute.textContent=v.muted||v.volume===0?'🔇':'🔊';volume.value=v.muted?0:v.volume});v.addEventListener('ended',update);seek.addEventListener('input',()=>{wasSeeking=true;const pct=Number(seek.value)/1000;seek.style.setProperty('--lb-progress',`${pct*100}%`);current.textContent=fmt(pct*(v.duration||0))});seek.addEventListener('change',()=>{if(v.duration)v.currentTime=(Number(seek.value)/1000)*v.duration;wasSeeking=false;update()});volume.addEventListener('input',()=>{v.volume=Number(volume.value);v.muted=v.volume===0});mute.addEventListener('click',()=>{v.muted=!v.muted});$id('lbBack').addEventListener('click',()=>{v.currentTime=Math.max(0,(v.currentTime||0)-10);flashToast('−10 seconds')});$id('lbForward').addEventListener('click',()=>{v.currentTime=Math.min(v.duration||Infinity,(v.currentTime||0)+10);flashToast('+10 seconds')});speed.addEventListener('change',()=>{v.playbackRate=Number(speed.value);flashToast(`Playback speed ${speed.options[speed.selectedIndex].text}`)});$id('lbFullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await box.requestFullscreen()}catch{if(v.webkitEnterFullscreen)v.webkitEnterFullscreen();else flashToast('Fullscreen unavailable in this browser')}});$id('lbTheater').addEventListener('click',()=>{const layout=box.closest('.watch-layout');const on=!box.classList.contains('lb-theater');box.classList.toggle('lb-theater',on);if(layout)layout.classList.toggle('lb-theater-layout',on);$id('lbTheater').textContent=on?'▱':'▰';$id('lbTheater').title=on?'Exit theater mode':'Theater mode'});box.addEventListener('mousemove',()=>{box.classList.add('lb-controls-active')});box.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea,button'))return;let used=true;switch(e.key.toLowerCase()){case' ':case'k':toggle();break;case'arrowleft':v.currentTime=Math.max(0,v.currentTime-5);break;case'arrowright':v.currentTime=Math.min(v.duration||Infinity,v.currentTime+5);break;case'arrowup':v.volume=Math.min(1,v.volume+.05);v.muted=false;break;case'arrowdown':v.volume=Math.max(0,v.volume-.05);break;case'm':v.muted=!v.muted;break;case'f':$id('lbFullscreen').click();break;default:used=false}if(used)e.preventDefault()});document.addEventListener('keydown',e=>{if(document.getElementById('watchView').classList.contains('hidden')||e.target.matches('input,textarea,select,button,[contenteditable="true"]'))return;if([' ','k','arrowleft','arrowright','arrowup','arrowdown','m','f'].includes(e.key.toLowerCase())&&box.contains(document.activeElement)){/* handled by player focus */}});document.addEventListener('fullscreenchange',()=>{$id('lbFullscreen').textContent=document.fullscreenElement?'⛶':'⛶';$id('lbFullscreen').title=document.fullscreenElement?'Exit fullscreen':'Fullscreen'});update()})();
